void App::paletteFilter() {
    if (!popupEdit) return;
    const auto query = lower(utf8(editText(popupEdit)));
    paletteItems.clear();
    for (const auto& [path, document] : documents) {
        if (lower(path).find(query) != std::string::npos) {
            paletteItems.push_back({wide(baseName(path)), wide(path), "open-file", path});
        }
    }
    if (popupMode != "files") {
        const std::vector<PaletteItem> commands = {
            {L"最近的文件", L"Ctrl E", "recent-files", ""},
            {L"文件结构", L"Ctrl F12", "file-outline", ""},
            {L"后退", L"Ctrl Alt ←", "navigate-back", ""},
            {L"前进", L"Ctrl Alt →", "navigate-forward", ""},
            {L"重新打开关闭的标签", L"Ctrl Shift T", "reopen-tab", ""},
            {L"新建文件", L"Ctrl Alt N", "new-file", ""},
            {L"运行当前 Python 文件", L"Shift F10", "run", ""},
            {L"运行全部单元测试", L"unittest", "tests", ""},
            {L"在项目中查找", L"Ctrl Shift F", "search", ""},
            {L"打开项目终端", L"Alt F12", "terminal", ""},
            {L"保存全部文件", L"Ctrl S", "save", ""},
            {L"导出整个项目", L"JSON", "export", ""},
            {L"导入文件 / 项目", L"", "import", ""},
            {L"创建本地检查点", L"", "checkpoint", ""},
            {L"外观设置", L"主题 / 字号", "settings", ""},
            {L"设置程序标准输入", L"input()", "stdin", ""},
            {L"快捷键与帮助", L"", "help", ""}
        };
        for (const auto& command : commands) {
            if (lower(utf8(command.label)).find(query) != std::string::npos) paletteItems.push_back(command);
        }
    }
    if (paletteItems.size() > 100) paletteItems.resize(100);
    selected = std::min(selected, std::max(0, static_cast<int>(paletteItems.size()) - 1));
    InvalidateRect(popup, nullptr, FALSE);
}
void App::paletteChoose(int index){if(index<0||index>=(int)paletteItems.size())return;auto item=paletteItems[index];closePopup();if(item.action=="search")setTool("search");else action(item.action,item.data);}
void App::popupSubmit(){try{
 auto mode=popupMode,data=popupData;std::string value=popupEdit?utf8(editText(popupEdit)):"";
 if(mode=="palette"||mode=="files"){paletteChoose(selected);return;}if(mode=="new-file"){newFile(trim(value));closePopup();}else if(mode=="rename"){renameFile(data,trim(value));closePopup();}else if(mode=="delete"){deleteFile(data);closePopup();}else if(mode=="restore"){int i=std::stoi(data);closePopup();restoreCheckpoint(i);}else if(mode=="goto"){int n=0;try{size_t at;n=std::stoi(trim(value),&at);if(at!=trim(value).size())n=0;}catch(...){n=0;}if(n<1||n>(int)sci(SCI_GETLINECOUNT))throw std::runtime_error("请输入有效行号");closePopup();gotoLine(n-1);}else if(mode=="checkpoint"){if(trim(value).empty())throw std::runtime_error("请输入检查点名称");closePopup();checkpoint(trim(value));}else if(mode=="stdin"){settings.stdinText=value;saveSession();closePopup();toast("标准输入已更新");}else if(mode=="find"||mode=="replace"){findInFile(mode=="replace");return;}else closePopup();
 }catch(const std::exception&ex){popupError=ex.what();if(popup)InvalidateRect(popup,nullptr,FALSE);}
}
void App::popupClick(float x,float y){for(auto hitIt=popupHits.rbegin();hitIt!=popupHits.rend();++hitIt)if(contains(hitIt->box,x,y)){auto a=*hitIt;if(a.action=="cancel")closePopup();else if(a.action=="submit")popupSubmit();else if(a.action=="choose")paletteChoose(a.index);else if(a.action=="theme"){settings.light=!settings.light;applySettings();}else if(a.action=="font"){std::vector<int>v={11,12,13,14,15,16,18,20};auto it=std::find(v.begin(),v.end(),settings.font);settings.font=v[(it-v.begin()+1)%v.size()];applySettings();}else if(a.action=="indent"){settings.tab=settings.tab==2?4:settings.tab==4?8:2;applySettings();}else if(a.action=="wrap"){settings.wrap=!settings.wrap;applySettings();}else if(a.action=="interpreter"){ComPtr<IFileOpenDialog>d;if(SUCCEEDED(CoCreateInstance(CLSID_FileOpenDialog,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&d)))){COMDLG_FILTERSPEC spec{L"Python 解释器",L"*.exe"};d->SetFileTypes(1,&spec);d->SetTitle(L"选择 Python 解释器，例如 .venv\\Scripts\\python.exe");if(SUCCEEDED(d->Show(popup))){ComPtr<IShellItem>i;d->GetResult(&i);PWSTR p=nullptr;if(SUCCEEDED(i->GetDisplayName(SIGDN_FILESYSPATH,&p))){settings.interpreter=p;CoTaskMemFree(p);saveSession();InvalidateRect(popup,nullptr,FALSE);}}}}return;}}
